// ==========================================
// ACCOUNTING & TRANSACTIONS VOUCHER TYPES (STANDARD ERP VOUCHERS)
// ==========================================
export type VoucherType =
  | 'payment'
  | 'receipt'
  | 'journal'
  | 'contra'
  | 'sales'
  | 'sales_return'
  | 'purchase'
  | 'purchase_return'
  | 'stock_journal'
  | 'debit_note'
  | 'credit_note'
  | 'delivery_challan'
  | 'sales_order'
  | 'purchase_order'
  | 'quotation'
  | 'proforma_invoice'
  | 'stock_transfer'
  | 'expense'
  | 'other_income'
  | 'invoice'
  | 'notes'
  | 'stock';

export interface StandardSalesVoucherItem {
  id: string;
  item_description: string;
  godown?: string;
  batch_serial?: string;
  qty: number | '';
  unit: string;
  price: number | '';
  disc_pct?: number | '';
  disc_amt?: number;
  tax_pct?: number | '';
  tax_amt?: number;
  amount: number;
}

export interface GodownMaster {
  id: string;
  name: string;
  location: string;
  capacity: string;
  manager: string;
}

export interface EmployeeMaster {
  id: string;
  name: string;
  role: string;
  dept: string;
  phone: string;
  salary?: number;
}

export interface SalesmanMaster {
  id: string;
  name: string;
  territory: string;
  commission: string;
  phone: string;
  sales: number;
}

export interface DeliveryPersonMaster {
  id: string;
  name: string;
  vehicle: string;
  phone: string;
  activeRuns: number;
}

export interface LedgerMaster {
  id: string;
  name: string;
  group: string;
  opening_balance: number;
  dr_cr: 'Dr' | 'Cr';
  pan_vat?: string;
  notes?: string;
}

export interface StandardSalesBillSundry {
  id: string;
  name: string;
  rate_pct?: number | '';
  amount: number | '';
  type: 'additive' | 'subtractive' | 'round_off';
}

export interface StandardSalesTransportInfo {
  driver_name: string;
  driver_phone: string;
  vehicle_no: string;
  delivery_person: string;
  transport_name?: string;
  station?: string;
  gr_rr_no?: string;
}

export interface JournalEntryRow {
  id: string;
  type: 'Dr' | 'Cr';
  account: string;
  amount: number | '';
  narration?: string;
}

export interface StockJournalRow {
  id: string;
  item_name: string;
  qty: number | '';
  unit: string;
  rate: number | '';
  amount: number | '';
  type: 'consumed' | 'produced' | 'transferred';
}

export interface VoucherAuditTrail {
  timestamp: string;
  user: string;
  action: string;
  note: string;
}

export interface AccountingVoucher {
  id: string;
  company_id?: string;
  voucher_type: VoucherType;
  voucher_number: string;
  date_bs: string;
  date_ad: string;
  account_debit: string;
  account_credit: string;
  amount: number;
  payment_mode?: 'Cash' | 'Bank' | 'Cheque' | 'IPS';
  cheque_number?: string;
  reference_no?: string;
  narration: string;
  created_at: string;
  party_id?: string;
  net_amount?: number;
  tax_amount?: number;
  // Sales Voucher extensions:
  series?: string;
  sale_type?: string;
  party_name?: string;
  mat_centre?: string;
  items?: StandardSalesVoucherItem[];
  bill_sundries?: StandardSalesBillSundry[];
  transport_info?: StandardSalesTransportInfo;
  is_held?: boolean;
  // Journal Multi-entry extension:
  journal_entries?: JournalEntryRow[];
  // Contra specific extension:
  contra_type?: 'cash_deposit' | 'cash_withdrawal' | 'inter_bank';
  // Debit / Credit Note extension:
  note_type?: 'Debit Note' | 'Credit Note';
  linked_invoice?: string;
  linked_invoice_date?: string;
  return_reason?: string;
  // Stock Journal extension:
  stock_mode?: 'transfer' | 'consumption_production';
  source_godown?: string;
  dest_godown?: string;
  stock_rows?: StockJournalRow[];
  // Audit Trail extension:
  audit_trail?: VoucherAuditTrail[];
  // Bill Outstanding & Partial Settlement extensions:
  remaining_amount?: number;
  bill_status?: 'Unpaid' | 'Partially Paid' | 'Paid';
  allocated_payments?: Array<{
    id: string;
    date_bs: string;
    amount: number;
    payment_mode: string;
    ref_no?: string;
  }>;
}

