      setItemMasters((prev) => {
        const updated = prev.filter((i) => i.id !== id);
        try { localStorage.setItem(`chequedesk_items_${activeCompanyId}`, JSON.stringify(updated)); } catch {}
        return updated;
      });
      showToast('Item Master successfully deleted', 'info');
